const referenceArt = {
  "home": "data:image/svg+xml;base64,",
  "sounds": "data:image/svg+xml;base64,",
  "progress": "data:image/svg+xml;base64,",
  "goal": "data:image/svg+xml;base64,",
  "grammar": "data:image/svg+xml;base64,",
  "words": "data:image/svg+xml;base64,",
  "chest": "data:image/svg+xml;base64,"
};

function referenceIcon(name, className = "") {
  return '<img class="reference-icon ' + className + '" src="' + referenceArt[name] + '" alt="" aria-hidden="true" draggable="false">';
}
